S = "Hakeem Force Academy"
QS = [
(S, "Which landlocked country can use Pakistan's seaports (Karachi, Port Qasim and Gwadar) for its sea trade?", ["Afghanistan", "Nepal", "Bhutan", "Iran"], 0, "Afghanistan has no coastline, so it uses Pakistan's ports under the Afghan Transit Trade arrangement. Central Asian states are also linked to these ports by road routes.", "Iran has its own coast, and Nepal and Bhutan are not connected to Pakistan.", [2510, 2511]),
(S, "Which language is mainly spoken in Chitral?", ["Khowar", "Sindhi", "Balochi", "Brahui"], 0, "Khowar (also called Chitrali) is the main local language of Chitral district.", "Khowar is the lingua franca of Chitral and is also spoken in parts of Gilgit-Baltistan.", [1284]),
(S, "Which is the latest (current) constitution of Pakistan?", ["Constitution of 1956", "Constitution of 1962", "Constitution of 1973", "Interim Constitution of 1972"], 2, "Pakistan's third and present constitution was passed in 1973 and enforced on 14 August 1973. It is still in force with amendments.", "The 1956 and 1962 constitutions were the earlier ones.", [4357]),
(S, "Who is the last prophet of Allah?", ["Hazrat Isa (AS)", "Hazrat Musa (AS)", "Hazrat Ibrahim (AS)", "Hazrat Muhammad (PBUH)"], 3, "Hazrat Muhammad (PBUH) is Khatam-un-Nabiyyin, the Seal of the Prophets, and no prophet comes after him.", "The Quran says this in Surah Al-Ahzab, verse 40.", [4544]),
(S, "Between which latitudes does Pakistan lie?", ["24 N to 37 N", "20 N to 30 N", "30 N to 45 N", "10 N to 25 N"], 0, "Pakistan extends from about 24 degrees north in the south to about 37 degrees north in the north.", "Pakistan's north-south extent is roughly 1,600 km.", [3180, 3181, 267]),
(S, "Between which longitudes does Pakistan lie?", ["50 E to 65 E", "61 E to 75 E", "70 E to 90 E", "55 E to 70 E"], 1, "Pakistan lies approximately between 61 degrees east and 75 degrees east longitude.", "Pakistan lies in the northern and eastern hemispheres.", [258]),
(S, "At which Inn of Court in London did Quaid-e-Azam Muhammad Ali Jinnah study law and qualify as a barrister?", ["Gray's Inn", "Inner Temple", "Middle Temple", "Lincoln's Inn"], 3, "Jinnah joined Lincoln's Inn in 1893 and was called to the bar in 1896, at the age of 19.", "He was the youngest Indian to be called to the bar at that time.", [1758, 1764]),
(S, "Which group of gases is mainly responsible for damaging the ozone layer?", ["Carbon dioxide", "Chlorofluorocarbons (CFCs)", "Methane", "Nitrogen"], 1, "CFCs release chlorine atoms in the stratosphere, and these break down ozone molecules.", "The Montreal Protocol of 1987 phased out the use of CFCs.", [492, 4020]),
(S, "Which mammal lays eggs?", ["Kangaroo", "Bat", "Platypus", "Dolphin"], 2, "The platypus is a monotreme, a rare mammal that lays eggs instead of giving birth to live young.", "The echidna is the other egg-laying mammal.", [360, 3866]),
(S, "What is the LCM of 3 and 8?", ["12", "16", "24", "32"], 2, "3 and 8 have no common factor, so LCM = 3 x 8 = 24.", "For two numbers, LCM x HCF equals their product.", [655]),
(S, "What type of legislature did the 1956 Constitution of Pakistan provide?", ["Bicameral", "Unicameral", "Tricameral", "No legislature"], 1, "The 1956 Constitution created a single-house (unicameral) National Assembly of 300 members.", "A bicameral legislature came with the 1973 Constitution (National Assembly and Senate).", [3491, 3502]),
(S, "Which country is known as the Land of Opportunities?", ["Russia", "Japan", "United States of America", "China"], 2, "The USA is popularly called the Land of Opportunities because it has long attracted immigrants seeking jobs and a better life.", "It is also called the Land of the Free and the Melting Pot.", [3965]),
(S, "Which province of Pakistan has the fewest National Assembly seats?", ["Khyber Pakhtunkhwa", "Sindh", "Punjab", "Balochistan"], 3, "Balochistan has only 16 general seats in the National Assembly, compared with 45 for KP, 61 for Sindh and 141 for Punjab.", "Punjab has the most seats because it has the largest population.", [4268]),
(S, "Which is the largest lake of North America by area?", ["Lake Superior", "Lake Michigan", "Lake Huron", "Lake Erie"], 0, "Lake Superior is the largest of the Great Lakes and the largest freshwater lake in North America by surface area.", "Lake Michigan is the largest Great Lake lying wholly inside the USA.", [653]),
]
